-- Integration fixtures are rolled back. No email is sent and no real attendee is touched.
begin;
set local role service_role;
do $$
declare e uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); foreign_sid uuid:=gen_random_uuid(); a jsonb; b jsonb; c jsonb; cid uuid:=gen_random_uuid(); bad uuid:=gen_random_uuid(); i integer; rejected boolean;
begin
 insert into events(id,slug,title) values(e,'registration-sql-'||e,'Registration transaction test'),(other,'registration-sql-'||other,'Other event');
 insert into event_sessions(id,event_id,code,title) values(sid,e,'TEST','Test session'),(foreign_sid,other,'OTHER','Other session');
 insert into event_registration_settings(event_id,config) values(e,jsonb_build_object('enabled',true,'mode','open','capacity',1,'allowWaitlist',true,'sessions',jsonb_build_array(jsonb_build_object('id',sid,'capacity',1,'allowWaitlist',true))));
 a:=save_event_registration(e,'one@example.invalid','One','Test','{}',array[sid],'public');
 if a->>'status'<>'registered' then raise exception 'Open signup did not register'; end if;
 b:=save_event_registration(e,'two@example.invalid','Two','Test','{}',array[sid],'public');
 if b->>'status'<>'waitlisted' then raise exception 'Full event did not waitlist'; end if;
 c:=save_event_registration(e,'ONE@example.invalid','Changed','Name','{}','{}','public');
 if c->>'id'<>a->>'id' or not (c->>'existing')::boolean or not exists(select 1 from event_registrant_sessions where registrant_id=(a->>'id')::uuid and session_id=sid) then raise exception 'Duplicate signup changed assignments'; end if;
 rejected:=false;
 begin perform save_event_registration(e,'wrong@example.invalid','X','Y','{}',array[foreign_sid],'admin'); exception when others then rejected:=true; end;
 if not rejected or exists(select 1 from event_registrants where event_id=e and email='wrong@example.invalid') then raise exception 'Cross-event failure was not atomic'; end if;
 rejected:=false;
 begin perform set_event_registration_status(e,(b->>'id')::uuid,'approved'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Promotion overbooked capacity'; end if;
 perform set_event_registration_status(e,(a->>'id')::uuid,'cancelled');
 perform set_event_registration_status(e,(b->>'id')::uuid,'approved');
 if not exists(select 1 from event_registrants where id=(b->>'id')::uuid and registration_status='approved') then raise exception 'Promotion failed after seat released'; end if;
 update event_registration_settings set config=config||'{"mode":"closed"}' where event_id=e;
 rejected:=false;
 begin perform save_event_registration(e,'closed@example.invalid','X','Y','{}','{}','public'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Closed event accepted signup'; end if;
 update event_registration_settings set config=config||'{"mode":"approval_required","capacity":null}' where event_id=e;
 c:=save_event_registration(e,'approval@example.invalid','X','Y','{}','{}','public');
 if c->>'status'<>'pending_approval' then raise exception 'Approval bypassed'; end if;
 update event_registration_settings set config=config||'{"mode":"invite_only"}' where event_id=e;
 rejected:=false;
 begin perform save_event_registration(e,'uninvited@example.invalid','X','Y','{}','{}','public'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Invite restriction bypassed'; end if;
 if not issue_registration_challenge(cid,e,'verify@example.invalid','login','correct','sql-test-ip','{}') then raise exception 'Challenge not issued'; end if;
 if consume_registration_challenge(cid,'wrong') is not null then raise exception 'Wrong code accepted'; end if;
 if consume_registration_challenge(cid,'correct')->>'email'<>'verify@example.invalid' then raise exception 'Correct code rejected'; end if;
 if consume_registration_challenge(cid,'correct') is not null then raise exception 'Code replay accepted'; end if;
 perform issue_registration_challenge(bad,e,'attempts@example.invalid','register','correct','sql-test-ip','{}');
 for i in 1..5 loop perform consume_registration_challenge(bad,'incorrect'); end loop;
 if consume_registration_challenge(bad,'correct') is not null then raise exception 'Attempt limit bypassed'; end if;
 for i in 1..3 loop if not issue_registration_challenge(gen_random_uuid(),e,'limit@example.invalid','login','x','sql-test-ip','{}') then raise exception 'Unexpected limit'; end if; end loop;
 if issue_registration_challenge(gen_random_uuid(),e,'limit@example.invalid','login','x','sql-test-ip','{}') then raise exception 'Email rate limit bypassed'; end if;
 insert into event_page_sections(event_id,page_key,sections,elements,document_revision) values(e,'event_home','[]','[]',1);
 perform publish_event_registration_page(e,'event_home',1,'{"enabled":false}');
 update event_page_sections set document_revision=2, sections='[{"id":"draft"}]' where event_id=e;
 if (select published_document->'sections' from event_page_sections where event_id=e)<>'[]'::jsonb then raise exception 'Draft leaked to publication'; end if;
 rejected:=false;
 begin perform publish_event_registration_page(e,'event_home',1,'{}'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Stale publish accepted'; end if;
 c:=save_jotform_registration('sql-test-'||e,e,'jotform@example.invalid','First','Test','{}',array[sid],'Registrant');
 perform save_jotform_registration('sql-test-'||e,e,'jotform@example.invalid','Replayed','Test','{}','{}','Registrant');
 if (select first_name from event_registrants where id=(c->>'id')::uuid)<>'First' then raise exception 'Webhook replay changed registration'; end if;
 for i in 1..1 loop
  if has_table_privilege('anon','event_registrants','SELECT') or has_table_privilege('authenticated','event_registration_challenges','SELECT') or has_function_privilege('anon','save_event_registration(uuid,text,text,text,jsonb,uuid[],text,text,text)','EXECUTE') then raise exception 'Public database privilege remains'; end if;
 end loop;
end $$;
rollback;
select 'Registration transaction, capacity, approval, invite, OTP, replay, rate-limit, publication and privilege checks passed' as result;
